import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Button, Badge } from 'react-bootstrap';
import { Link } from 'react-router-dom';

const PortfolioList = () => {
  const [portfolios, setPortfolios] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // In a real application, this would be an API call
    // For demo purposes, we'll use mock data
    const mockPortfolios = [
      {
        id: 1,
        name: 'My Stock Portfolio',
        created: '2025-03-02',
        lastUpdated: '2025-03-02',
        value: 25876.42,
        return: 15.3,
        riskRating: 'Moderate',
        assets: 12
      }
    ];

    // Simulate API call
    setTimeout(() => {
      setPortfolios(mockPortfolios);
      setLoading(false);
    }, 800);
  }, []);

  return (
    <Container className="mt-4">
      <Row className="mb-4 align-items-center">
        <Col>
          <h1>My Portfolios</h1>
        </Col>
        <Col xs="auto">
          <Button as={Link} to="/import" variant="primary">
            Import New Portfolio
          </Button>
        </Col>
      </Row>

      {loading ? (
        <Card>
          <Card.Body className="text-center py-5">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Loading...</span>
            </div>
            <p className="mt-3">Loading your portfolios...</p>
          </Card.Body>
        </Card>
      ) : portfolios.length === 0 ? (
        <Card>
          <Card.Body className="text-center py-5">
            <h4>No portfolios found</h4>
            <p>Get started by importing your first portfolio</p>
            <Button as={Link} to="/import" variant="primary">
              Import Portfolio
            </Button>
          </Card.Body>
        </Card>
      ) : (
        <Row>
          {portfolios.map(portfolio => (
            <Col md={12} key={portfolio.id} className="mb-4">
              <Card className="card-hover h-100">
                <Card.Body>
                  <Row>
                    <Col md={8}>
                      <Card.Title>
                        <Link to={`/portfolios/${portfolio.id}`} className="text-decoration-none">
                          {portfolio.name}
                        </Link>
                      </Card.Title>
                      <Card.Text className="text-muted">
                        Created: {portfolio.created} | Last updated: {portfolio.lastUpdated}
                      </Card.Text>
                      <Table responsive className="mt-3">
                        <thead>
                          <tr>
                            <th>Current Value</th>
                            <th>Return</th>
                            <th>Risk Rating</th>
                            <th>Assets</th>
                          </tr>
                        </thead>
                        <tbody>
                          <tr>
                            <td>${portfolio.value.toLocaleString()}</td>
                            <td className={portfolio.return >= 0 ? 'text-success' : 'text-danger'}>
                              {portfolio.return >= 0 ? '+' : ''}{portfolio.return}%
                            </td>
                            <td>
                              <Badge bg={
                                portfolio.riskRating === 'Low' ? 'success' :
                                portfolio.riskRating === 'Moderate' ? 'warning' : 'danger'
                              }>
                                {portfolio.riskRating}
                              </Badge>
                            </td>
                            <td>{portfolio.assets}</td>
                          </tr>
                        </tbody>
                      </Table>
                    </Col>
                    <Col md={4} className="d-flex flex-column justify-content-between">
                      <div>
                        <h5>Quick Actions</h5>
                        <div className="d-grid gap-2">
                          <Button as={Link} to={`/portfolios/${portfolio.id}`} variant="outline-primary" size="sm">
                            View Details
                          </Button>
                          <Button as={Link} to={`/performance?portfolio=${portfolio.id}`} variant="outline-primary" size="sm">
                            Performance Analysis
                          </Button>
                          <Button as={Link} to={`/tax?portfolio=${portfolio.id}`} variant="outline-primary" size="sm">
                            Tax Analysis
                          </Button>
                        </div>
                      </div>
                    </Col>
                  </Row>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      )}
    </Container>
  );
};

export default PortfolioList;
